<template><view :class="['app-page',{dark}]"><ui-header title="钱包" back/><view class="wallet-card"><view class="wallet-head"><view class="wallet-icon"><ui-icon name="wallet" :size="44" tone="white"/></view><text>{{isProvider?'服务收益':'钱包余额'}}</text></view><view class="money">¥{{balance.toFixed(2)}}</view><view class="wallet-actions"><view class="detail-link" @tap="goDetail"><text>查看明细</text><ui-icon name="chevron-right" :size="25" tone="white"/></view><view v-if="isProvider" class="withdraw" @tap="goWithdraw"><text>提现</text><ui-icon name="chevron-right" :size="25"/></view></view></view></view></template>
<script>import{isDark}from'@/utils/app';import{api}from'@/services/api';export default{data(){return{dark:false,balance:0,userType:'user'}},computed:{isProvider(){return this.userType==='player'}},onShow(){this.dark=isDark();const user=uni.getStorageSync('user')||{};this.userType=user.userType||'user';api.getWallet().then(data=>{const balance=Number(data.balance||0);if(!Number.isFinite(balance))throw new Error('钱包金额异常');this.balance=balance}).catch(()=>{uni.showToast({title:'钱包加载失败，请重新进入',icon:'none'})});api.getProfile().then(profile=>{this.userType=profile.userType||'user'}).catch(()=>{})},methods:{goWithdraw(){if(!this.isProvider)return;uni.navigateTo({url:'/pages/wallet/withdraw'})},goDetail(){uni.navigateTo({url:'/pages/wallet/detail'})}}}</script>
<style scoped>.wallet-card{position:relative;margin:28rpx;padding:34rpx;border-radius:26rpx;background:linear-gradient(125deg,#6079e9,#9a72e5);color:#fff;box-shadow:0 18rpx 46rpx rgba(80,91,194,.24)}.wallet-head{display:flex;align-items:center;gap:14rpx;font-size:26rpx}.wallet-icon{width:62rpx;height:62rpx;display:flex;align-items:center;justify-content:center;border-radius:20rpx;background:rgba(255,255,255,.18)}.money{margin:24rpx 0 32rpx;font-size:52rpx;font-weight:900}.wallet-actions{display:flex;align-items:center;justify-content:space-between}.detail-link,.withdraw{display:flex;align-items:center;gap:4rpx;font-size:24rpx}.withdraw{height:58rpx;padding:0 24rpx;border-radius:30rpx;background:#fff;color:#6256a0}</style>
